INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(15339, 0, 0, 'plPL', 'Moje siły odżyły!'),
(15339, 0, 1, 'plPL', 'Moje moce się odnowiły!'),
(15339, 0, 2, 'plPL', 'Moje moce powracają!'),
(15339, 1, 0, 'plPL', 'Brońcie miasta za wszelką cenę!'),
(15339, 1, 1, 'plPL', 'Na stanowiska. Brońcie miasta.'),
(15339, 1, 2, 'plPL', 'Intruzi zostaną zlikwidowani.'),
(15341, 6, 0, 'plPL', 'Atakujcie i niech drogo za to zapłacą!'),
(15341, 7, 0, 'plPL', 'Zmiażdżcie ich! Wypędźcie ich!'),
(15341, 8, 0, 'plPL', 'Nie wahajcie się! Zniszczcie ich!');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(11018, 'plPL', '%s kontratakuje w odwecie.', '', 0),
(11067, 'plPL', 'Nie jesteś $gwart:warta; mojego czasu, $n!', '', 0),
(11074, 'plPL', '%s upatruje sobie $n!', '', 0),
(11429, 'plPL', 'Wkrótce poznacie cenę swojego wtrącania się, śmiertelnicy... Mistrz jest już niemal cały... A gdy powstanie, wasz świat przestanie istnieć.', '', 0),
(11433, 'plPL', 'Wydaj ostatnie tchnienie!', '', 0),
(11434, 'plPL', 'Wojownicy, kapitanowie, walczcie dalej!', '', 0),
(11435, 'plPL', 'Bezczelny głupcze! Sam cię zabiję!', '', 0),
(11436, 'plPL', 'Fandralu! Nadszedł twój czas! Idź i ukryj się w Szmaragdowym Śnie, i módl się, żebyśmy cię nigdy nie znaleźli!\n', '', 0),
(11437, 'plPL', 'Jeleniorogi będzie skomlał i błagał o życie, tak jak ten szczeniak, jego syn! Tysiąc lat niesprawiedliwości skończy się dzisiaj!\n', '', 0),
(11438, 'plPL', 'Strach jest dla wroga! Strach i śmierć!', '', 0),
(11439, 'plPL', 'Nie będziemy już dłużej czekać za zaryglowanymi drzwiami i kamiennymi murami! Nikt już nie odmówi nam zemsty! Same smoki zadrżą przed naszym gniewem!\n', '', 0),
(11440, 'plPL', 'Nadchodzi czas naszej odpłaty! Niech ciemność zapanuje w sercach naszych wrogów!', '', 0),
(11441, 'plPL', '%s wyczuwa twój strach.', '', 0),
(11449, 'plPL', 'Piaski pustyni, powstańcie i przesłońcie słońce!', '', 0),
(11450, 'plPL', 'Zostajesz $gzlikwidowany:zlikwidowana;.', '', 0),
(11451, 'plPL', 'To... moja... porażka.', '', 0),
(11474, 'plPL', '%s wysysa twoją manę i zamienia się w kamień.', '', 0),
(11720, 'plPL', 'Mury zostały przełamane!', '', 0),
(12781, 'plPL', '%s aż iskrzy od energii!', '', 0);
